<script setup lang="ts">import{Head,Link,router}from'@inertiajs/vue3';import ErpLayout from '@/Layouts/ErpLayout.vue';import type{BankStatementDetail}from'@/Types/treasury';defineOptions({layout:ErpLayout});const props=defineProps<{statement:BankStatementDetail;canCreateReconciliation:boolean}>();const money=(v:string|null):string=>v===null?'—':new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:6}).format(Number(v));const remove=():void=>{if(window.confirm('Delete this bank statement?'))router.delete(route('bank-statements.destroy',props.statement.id));};</script>
<template><Head :title="statement.statement_reference"/><div class="space-y-6"><div class="flex justify-between gap-4"><div><Link :href="route('bank-statements.index')" class="text-sm text-brand-600">Bank Statements</Link><h1 class="mt-2 text-2xl font-semibold">{{statement.statement_reference}}</h1><p class="mt-1 text-sm text-gray-500">{{statement.source_filename}}</p></div><div class="flex gap-2"><Link v-if="canCreateReconciliation" :href="route('bank-reconciliations.create',{bank_statement_import_id:statement.id})" class="rounded-lg bg-brand-500 px-4 py-2.5 text-sm text-white">Start Reconciliation</Link><button v-if="statement.can.delete" class="rounded-lg border border-error-300 px-4 py-2.5 text-sm text-error-600" @click="remove">Delete</button></div></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="x in [['Period',`${statement.period_start} to ${statement.period_end}`],['Opening',money(statement.opening_balance)],['Closing',money(statement.closing_balance)],['Lines',String(statement.line_count)]]" :key="String(x[0])" class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><p class="text-xs uppercase text-gray-500">{{x[0]}}</p><p class="mt-2 font-semibold">{{x[1]}}</p></div></div><div class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><p class="font-medium">{{statement.bank_account?.code}} — {{statement.bank_account?.name}}</p><p class="text-sm text-gray-500">{{statement.branch?.name}} · {{statement.currency_code}} · Imported by {{statement.imported_by?.name??'—'}}</p></div><div class="overflow-hidden rounded-2xl border bg-white dark:border-gray-800 dark:bg-gray-900"><div class="overflow-x-auto"><table class="min-w-[1100px] w-full"><thead class="bg-gray-50 dark:bg-white/[.03]"><tr><th class="p-3 text-left text-xs uppercase text-gray-500"># / Date</th><th class="p-3 text-left text-xs uppercase text-gray-500">Reference</th><th class="p-3 text-left text-xs uppercase text-gray-500">Description</th><th class="p-3 text-right text-xs uppercase text-gray-500">Debit</th><th class="p-3 text-right text-xs uppercase text-gray-500">Credit</th><th class="p-3 text-right text-xs uppercase text-gray-500">Balance</th><th class="p-3 text-left text-xs uppercase text-gray-500">Status</th></tr></thead><tbody class="divide-y dark:divide-gray-800"><tr v-for="l in statement.lines" :key="l.id"><td class="p-3 text-sm">{{l.line_number}}<p class="text-xs text-gray-500">{{l.transaction_date}}</p></td><td class="p-3 text-sm">{{l.bank_reference??'—'}}</td><td class="p-3 text-sm">{{l.description??'—'}}</td><td class="p-3 text-right text-sm">{{money(l.debit_amount)}}</td><td class="p-3 text-right text-sm">{{money(l.credit_amount)}}</td><td class="p-3 text-right text-sm font-medium">{{money(l.running_balance)}}</td><td class="p-3"><span class="rounded-full bg-gray-100 px-2 py-1 text-xs dark:bg-gray-800">{{l.status}}</span></td></tr></tbody></table></div></div><div v-if="statement.reconciliations.length" class="rounded-2xl border bg-white p-5 dark:border-gray-800 dark:bg-gray-900"><h2 class="text-lg font-semibold">Reconciliation History</h2><div class="mt-4 space-y-2"><Link v-for="r in statement.reconciliations" :key="r.id" :href="route('bank-reconciliations.show',r.id)" class="flex justify-between rounded-lg border p-3 text-sm dark:border-gray-800"><span>{{r.reconciliation_number??`Session #${r.id}`}}</span><span>{{r.status_label}} · Difference {{money(r.difference_amount)}}</span></Link></div></div></div></template>
